public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        throw new IllegalArgumentException("Input list cannot be null or empty.");
    }

    int maxLength = 0;
    String currentSubstring = "";

    for (String str : strings) {
        for (int i = 0; i <= str.length(); i++) {
            currentSubstring = str.substring(i);
            String inverseSubstring = new StringBuilder(currentSubstring).reverse().toString();
            if (strings.contains(currentSubstring) || strings.contains(inverseSubstring)) {
                if (currentSubstring.length() > maxLength) {
                    maxLength = currentSubstring.length();
                }
            }
        }
    }

    return maxLength;
}

