public static int countDoubles(int[] numbers) {
    if (numbers == null) {
        throw new IllegalArgumentException("Input array cannot be null");
    }
    if (numbers.length == 0) {
        return 0;
    }

    int doubleCount = 0;
    // Use a HashSet to store numbers that have been seen so far
    HashSet<Integer> seen = new HashSet<>();

    for (int num : numbers) {
        if (seen.contains(num * 2)) {
            doubleCount++;
        }
        seen.add(num);
    }

    return doubleCount;
}

