public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Check if the starting and end coordinates are within the bounds of the n-termining space
    if (start[0] < 0 || start[0] >= n || start[1] < 0 || start[1] >= n
        || end[0] < 0 || end[0] >= n || end[1] < 0 || end[1] >= n) {
        return "cannot be travelled since invalid coordinates";
    }

    // Check if the start and end coordinates are the same
    if (Arrays.equals(start, end)) {
        return "can be travelled since same coordinates";
    }

    // Create a set of all coordinates to keep track of visited nodes
    Set<Integer> visited = new HashSet<>();
    Stack<int[]> stack = new Stack<>();

    // Add the starting coordinate to the stack and mark it as visited
    stack.push(new int[]{start[0], start[1]});
    visited.add(start[0] + n * start[1]);

    // Traverse the maze using DFS
    while (!stack.isEmpty()) {
        int[] current = stack.pop();
        int x = current[0];
        int y = current[1];

        // Check if the current coordinates are the end coordinates
        if (Arrays.equals(current, end)) {
            return "can be travelled";
        }

        // Get the valid neighbors of the current coordinates
        int[][] neighbors = getNeighbors(x, y, n, paths);
        for (int[] neighbor : neighbors) {
            int neighborX = neighbor[0];
            int neighborY = neighbor[1];

            // Check if the neighbor coordinates are within the bounds of the n-termining space and have not been visited
            if (neighborX >= 0 && neighborX < n && neighborY >= 0 && neighborY < n
                && !visited.contains(neighborX + n * neighborY)) {
                // Add the neighbor coordinates to the stack and mark it as visited
                stack.push(neighbor);
                visited.add(neighborX + n * neighborY);
            }
        }
    }

    // If the end coordinates are not reached, return "cannot be travelled"
    return "cannot be travelled";
}

