public static String appx(String word1, String word2) {
    // Convert input words to lowercase to ensure case-insensitivity and simplicity
    word1 = word1.toLowerCase();
    word2 = word2.toLowerCase();

    // If the input strings are the same, the appx value is 1
    if (word1.equals(word2)) {
        return "appx(" + word1 + ", " + word2 + ") = 1";
    }

    // Create sets of characters from both words to remove duplicate characters
    Set<Character> set1 = new HashSet<>(word1.toCharArray());
    Set<Character> set2 = new HashSet<>(word2.toCharArray());

    // Calculate the intersection of both sets to find common letters
    Set<Character> commonLetters = new HashSet<>(set1);
    commonLetters.retainAll(set2);

    // Convert the number of common letters to an integer
    int commonCount = commonLetters.size();

    // Calculate the simplified fraction of common letters to the sum of the lengths of the words
    int simplifiedFractionNumerator = commonCount;
    int simplifiedFractionDenominator = word1.length() + word2.length();

    // Return the simplified fraction in the requested format
    return "appx(" + word1 + ", " + word2 + ") = " + simplifiedFractionNumerator + "/" + simplifiedFractionDenominator;
}

