public static String convertDatesToWeekdays(String date) {
    try {
        DateTimeFormatter formatter = DateTimeFormatter.ofPattern("MM dd yyyy");
        LocalDate localDate = LocalDate.parse(date, formatter);

        WeekFields weekFields = WeekFields.of(Locale.getDefault());
        int dayOfWeekIndex = localDate.get(weekFields.dayOfWeek());
        String dayOfWeek = localDate.getDayOfWeek().getDisplayName(TextStyle.FULL, Locale.getDefault());
        String result = format("on " + date + " is a %s", dayOfWeek.);
        return result;
    } catch (Exception e) {
        return "Invalid date format. Please provide a date in the format 'MM dd yyyy'.";
    }
}

