public double trimMean(int[] arr) {
    int n = arr.length;
    Arrays.sort(arr);
    int trimmedSize = (int) Math.ceil((double)n * 0.05);
    int trimmedEnd = n - trimmedSize;
    double sum = 0;
    for (int i = trimmedEnd; i < n - trimmedEnd; i++) {
        sum += arr[i];
    }
    return Math.round(sum * 100000 / (n - trimmedSize * 2)) / 100000.0;
}

