public boolean hasAllCodes(String s, int k) {
    int n = s.length();
    int m = n - k + 1;
    Map<String, Integer> seen = new HashMap<>();
    if (m < k) return false; // Not enough substrings to cover all combinations

    for (int i = 0; i < m; i++) {
        String sub = s.substring(i, i + k);
        seen.put(sub, seen.getOrDefault(sub, 0) + 1);
        if (seen.get(sub) > 1) return false; // Duplicate substring found
    }

    return true;
}

