    int positions = 1;

    // Loop through the string length from n to 1
    for (int i = n; i > 0; i--) {
        int remainder = k % i;

        // Check if remainder is zero, if it is, append a 'z'
        if (remainder == 0) {
            result.append('z');
        } else {
            // Calculate the character to append by subtracting the remainder from 1 and adding 'a' (ASCII value of 'a' is 97)
            result.append((char) (97 + (remainder - 1)));
        }

        // Subtract the current character's value from k
        k -= remainder;
    }

    // Reverse the resulting string to get the correct lexicographical order
    return result.reverse().toString();
}

