public static int[] diagonalOrder(int[][] mat) {
        if (mat == null || mat.length == 0 || mat[0].length == 0) {
            return new int[0];
        }

        int numRows = mat.length;
        int numCols = mat[0].length;
        int[] diagonal = new int[numRows * numCols];

        int row = 0;
        int col = 0;
        int count = 0;

        while (count < numRows * numCols) {
            diagonal[count++] = mat[row][col];

            if (col == numCols - 1) {
                row++;
            } else if (row == 0) {
                col++;
            } else {
                row--;
                col++;
            }
        }

        return diagonal;
    }

