public static List<String> centerSymmetricNumbers(int n) {
        if (n <= 0) {
            throw new IllegalArgumentException("Input must be a positive integer");
        }
        List<String> centerSymmetricNumbers = new ArrayList<>();
        int base = (int) Math.pow(10, n / 2 - 1);
        int digitCount = n - n / 2;

        for (int i = 0; i < base; i++) {
            String centerSubstring = String.valueOf(i);
            if (centerSubstring.length() == digitCount) {
                centerSymmetricNumbers.add(centerSubstring);
            }
        }

        // Capitalize the first character
        for (String number : centerSymmetricNumbers) {
            number = number.charAt(0) + number.substring(1);
        }

        return centerSymmetricNumbers;
    }

